"""Document verified production and installation results without inventing runtime tests."""
from pathlib import Path
import json,hashlib,re
R=Path(__file__).resolve().parents[1];O=R/'docs/verification/gorynych-1.9.6'
def main():
 gate=json.loads((O/'resource-gates.json').read_text(encoding='utf-8'))
 install=json.loads((O/'polymc-installation.json').read_text(encoding='utf-8-sig'))
 jar=R/'build/libs/slavicmyths-1.9.6.jar'
 digest=hashlib.sha256(jar.read_bytes()).hexdigest()
 assert gate['status']==install['status']=='PASS' and gate['sha256']==install['sha256']==digest
 log=(R/'.tools/gorynych-clean-build.log').read_text(encoding='utf-8',errors='replace')
 build=next(s for s in log.splitlines() if 'BUILD SUCCESSFUL' in s)
 summary='''## Змей Горыныч — 1.9.6, 2026-10-13

Добавлен сюжетный Горыныч Змеиной горы: один привязанный к instance босс, три отдельные multipart головы, серверные логические 3600 HP, наземная и воздушная фазы, появление крыльев при 50%, несмертельное поражение при 5%, очищение порошком/пеплом/водой в любом порядке, живая мирная форма. Яйцо `zmey_gorynych_spawn_egg` находится в существующей вкладке «Мобы» и создаёт самостоятельный бой без сюжетных требований. Самостоятельные экземпляры не выдают сюжетные награды.

Worldgen, завершение команды создания горы и загрузка её чанков подключены к локальному населению; проверяются UUID, последнее место и готовность entity chunks. Повторное посещение существующей горы также подключено. Девять размеченных точек, переходы между крупными верхними помещениями, отдельные нижние компоненты; перед второй фазой выполняется явная сцена выхода в открытый двор. Под потолками/в интерьерах шеи, хвост и крылья складываются. При движении и поиске пути не используются принудительные загрузки чанков.

Реализованы независимые атаки голов с бюджетом двух крупных действий, захват с сопротивлением/помощью и пределом три секунды, каменные копья с геометрическим эффектом, хвост, дождь Мора, огненная бомбардировка, ветер, пикирование и десятисекундные наземные окна. Три временных собираемых дыхания расходуют общие три порции области. Снаряды/области не портят блоки; их время жизни и количество ограничены.

После полного очищения участникам выдаются 4 чешуи, печать и одна равновероятная руна; полному инвентарю оставляется ожидающая персональная награда. Receipt игрока сохраняется вместе с инвентарём до world claim. Чешуя после спасения — одна на игрока раз в 72000 тиков. Три руны интегрированы в существующую установку/слоты и реальные hit events. Змеиный арбалет/сталь добавлены в лут крепости; арбалет трёх дыханий хранит раздельные заряды и использует vanilla arrows. Улучшения оружия/четырёх частей перунитовой брони сохраняют допустимые компоненты и долю износа. Все четыре части имеют отдельную worn geometry и эффекты.

Для связки оберега сохранён ID `mor_ward`: обе детали хранителей + существующее Око Мора создают собранный многоразовый экземпляр с `GuardianWard196`. Ранние экземпляры остаются расходуемыми. Защита горы требует победы над заражённым Лихом, обоих персональных получений фрагментов и наличия/действия оберега; активные атаки Горыныча этим оберегом не блокируются. Ownerless crafter сохраняет запрет персонального рецепта. Новый портал, измерение и объединённая руна не добавлялись.

Native mesh: 40 bones, 292 cuboids, 7008 проверенных UV vertices; 9 согласованных appearance atlases, реальные 3D состояния арбалетов, 4 worn armor models, три разные рунические иконки, 31 собственный синтезированный OGG. Генератор воспроизводит актуальные ресурсы и Java mesh; существующие генераторы горы/финальной 1.8.5 сохраняют новую интеграцию.

'''
 results=f'''{build}. Девять offline наборов — PASS; {gate['checks']} production/resource gates — PASS. PolyMC Testing установлен на 1.9.6, SHA256 `{digest}`; {install['other_files_preserved']} остальных файлов профиля сохранены побайтно. Реальных запусков клиента/сервера/PolyMC/GameTest: **0**. Gameplay/MP/перезаход, seed QA, runtime visuals/audio, MSPT/FPS: **NOT_RUN / NOT_MEASURED**. NBT roundtrip и offline projection не являются игровым тестом. [Отчёт](verification/gorynych-1.9.6/REPORT.md).

'''
 for name in ['PROJECT_STATUS.md','ROADMAP.md','ARCHITECTURE.md']:
  p=R/'docs'/name;old=p.read_text(encoding='utf-8-sig');p.write_text(summary+results+old,encoding='utf-8')
 checks='\n'.join('- '+s.strip() for s in log.splitlines() if 'OFFLINE_PASS' in s or '120 native block' in s)
 report='# Змей Горыныч — 1.9.6\n\n'+summary.split('\n',1)[1]+results+f'''
## Подтверждённые проверки

{checks}

- Проверены границы UV native meshes, четыре различные wearable geometry, именованные шеи/челюсти/лапы/крылья; Java 21 bytecode и точное соответствие production JAR исходным ресурсам/классам.
- Pure admission/HP checks проверяют произвольный overkill и восемь масок очищения. SavedData roundtrip проверяет world UUID, HP/состояние/очищение/крылья, участников и claims. Native ItemStack test проверяет копирование имени/компонентов и доли износа. Это не реальный бой/перезаход.
- Сравнение с точной предыдущей 1.9.5.1: прежние ресурсы сохранены. Семь изменённых ресурсов относятся к локализациям, sounds, equipment mixin, fire damage tag, луту крепости и существующему рецепту оберега.
- Все собственные OGG существуют; ссылки на модели/текстуры и RU/EN проверены. Общий/server код не импортирует клиентские классы. Тестовый код/`tools/smoke` отсутствует в production.

## Установка

Профиль: `{install['instance']}`.

JAR: `{install['installed_jar']}`.

SHA256: `{digest}`.

Backup непосредственно заменённого JAR: `{install['backup']}`. Установщик сохранил {install['other_files_preserved']} прочих файлов профиля; миры/конфигурации не изменены. Старый 1.16.5 не затронут. Клиент/сервер установщиком не запускались.

## Короткая игровая проверка — пока NOT_RUN

1. В отдельном тестовом мире/копии открыть вкладку «Мобы», найти яйцо Горыныча и вызвать на свободной площадке. Проверить три головы, походку/крылья, телеграфы, захват и освобождение. Самостоятельное яйцо не требует оберег/репутацию.
2. Создать гору операторской командой `/slavicmyths generate_serpent_hill`, дождаться завершения; проверить одного сюжетного босса. В отдельном natural seed найти новую гору. Проверить обе дороги, нижний старт/верхний старт, комнаты и повороты структуры.
3. Довести до 50% под землёй, проверить сцену выхода, полёт/пикирование/посадки. Довести любым сильным ударом до 5%; проверить отсутствие смерти и продолжение после реального перезахода.
4. Очистить головы разными игроками в любом порядке; неверные/повторные клики не расходуют реагенты. Проверить все маски, чистую форму с прежним UUID, три персональные награды, полный инвентарь, повторные входы/выгрузки и ограничение сброшенной чешуи.
5. Собрать три дыхания с общими лимитами; проверить урон зон при надетом обереге. Проверить три руны в допустимых/недопустимых слотах, апгрейды с чарами/именем/рунами/износом, режимы/заряды/обычные стрелы и возврат бутылок.
6. Проверить каждую часть брони при надевании/снятии, полный комплект/CD, многоразовый собранный оберег и сохранение персональных gates; проверить отсутствие специального рецепта оберега через ownerless crafter.

Не выполнены реальные client/server/GameTest/MP запуски, игровые измерения MSPT/FPS и игровая визуальная/звуковая приёмка. Сборка не подтверждает эти сценарии.
'''
 (O/'REPORT.md').write_text(report,encoding='utf-8')
 guide='''# Использование 1.9.6

Яйцо: вкладка «Мобы» → «Яйцо призыва Змея Горыныча» (`slavicmyths:zmey_gorynych_spawn_egg`). Для самостоятельного тестового боя выбирайте свободную площадку; сюжетные награды связаны с естественным обитателем горы.

Босс появляется в новой/загруженной Змеиной горе, включая команду генерации. При 5% HP остаётся жив: ПКМ по отдельным головам — левая очищающим порошком, средняя пеплом очищения, правая очищенной водой. Порядок произвольный. После спасения ПКМ по Горынычу позволяет получить ожидающую награду/сброшенную чешую при выполнении персональных условий.

| Крафт | Материалы (каждая отдельная единица — в своей ячейке стола 3×3) |
|---|---|
| Собранный оберег `mor_ward` | Огненный фрагмент + водный фрагмент + Око Мора, три ячейки в одном ряду шириной 3; действует персональная сюжетная проверка Лиха/знаний |
| Арбалет трёх дыханий | Змеиный арбалет + чешуя + древняя змеиная сталь + по одной бутылке Мора, огня и бури |
| Драконий шлем/нагрудник/поножи/ботинки | Соответствующая перунитовая часть + чешуя + 2 перунита + 2 алмаза |

Арбалет: Shift+ПКМ разряженным переключает режим. При успешной зарядке одна бутылка выбранного дыхания даёт три заряда, пустая бутылка возвращается; запас раздельный по трём режимам. Без специального запаса работают обычные стрелы. Имя, применимые чары/руны и доля износа сохраняются при апгрейде.

Награда за спасение: 4 чешуи, печать и одна случайная руна. Требуются 3 свободных слота; при нехватке места освободите их и вернитесь/нажмите ПКМ. Дополнительная чешуя доступна участнику спустя 72000 тиков мира (три игровых дня), затем снова с тем же интервалом.

Надетый полный драконий комплект при HP <30% даёт Сопротивление I на 5 секунд с CD 180 секунд. Отдельные части: шлем −25% длительности обычных слепоты/тьмы/тошноты, нагрудник −15% урона огня/взрывов, поножи −30% силы отбрасывания, ботинки −35% падения.

Все игровые сценарии выше пока требуют ручной приёмки: агент не запускал игру.
'''
 (R/'docs/GORYNYCH_1.9.6.md').write_text(guide,encoding='utf-8')
 (O/'ASSET_LICENSE.md').write_text('# Происхождение assets\n\nГеометрия, пиксельные текстуры и синтезированные звуки созданы локальными воспроизводимыми генераторами этого проекта. Звуки не копируются из игр/модов. Приложенные пользователем художественные листы сохранены в docs/specs/1.9.6 как референсы; исходные изображения референсов не включаются в production JAR. Offline preview — проекция авторской геометрии, не игровой screenshot.\n',encoding='utf-8')
 for name in ['README.md','CHANGELOG.md']:
  p=R/name
  if p.exists():p.write_text('## 1.9.6 — Змей Горыныч\n\nГорыныч Змеиной горы, яйцо в творческой вкладке «Мобы», два этапа боя и очищение трёх голов, собираемые дыхания, персональные награды, арбалеты, три руны и драконья броня. PolyMC Testing обновлён после clean build и offline/resource gates. Игровых запусков агентом: 0. [Использование](docs/GORYNYCH_1.9.6.md), [результаты](docs/verification/gorynych-1.9.6/REPORT.md).\n\n'+p.read_text(encoding='utf-8-sig'),encoding='utf-8')
 print('GORYNYCH_REPORT_DOCS_PASS')
if __name__=='__main__':main()
